import{_ as t}from"./chunks/visibility_progress.hOO4BvNJ.js";import{_ as a,c as i,b as s,a0 as r}from"./chunks/framework.DZ_FiXNr.js";const m=JSON.parse(`{"title":"Visibility Progress","description":"See how your podcast's visibility changes over time, inspect its contributing factors, and review actions and observed signals from the same period.","frontmatter":{},"headers":[],"relativePath":"features/visibility-progress.md","filePath":"features/visibility-progress.md"}`),o={name:"features/visibility-progress.md"};function n(l,e,d,c,h,g){return s(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="visibility-progress" tabindex="-1">Visibility Progress <a class="header-anchor" href="#visibility-progress" aria-label="Permalink to &quot;Visibility Progress&quot;">​</a></h1><p>See how your podcast&#39;s visibility changes over time, inspect its contributing factors, and review actions and observed signals from the same period.</p><p><strong>To access:</strong> <strong>Traction → Visibility Progress</strong>.</p><p><a href="/images/visibility_progress.webp" title="Open screenshot at full size"><img src="'+t+'" alt="Visibility Progress dashboard" width="600px" style="display:block;margin:0 auto;"></a></p><h2 id="read-your-visibility-score" tabindex="-1">Read your Visibility Score <a class="header-anchor" href="#read-your-visibility-score" aria-label="Permalink to &quot;Read your Visibility Score&quot;">​</a></h2><p>The headline <strong>Visibility Score</strong> summarizes your show&#39;s measured discovery opportunities on a <strong>0–10 scale</strong>. A <strong>Top X%</strong> badge shows your relative placement when a rank is available; otherwise you see <strong>Rank pending</strong>. A short summary can highlight notable movement during the period.</p><p>The chart opens in <strong>Weekly</strong> view, which averages the daily scores within each week. Switch to <strong>Daily</strong> for individual readings. A quieter weekly line does not mean the daily changes disappeared; the two views summarize the same history differently.</p><h2 id="inspect-the-contributing-factors" tabindex="-1">Inspect the contributing factors <a class="header-anchor" href="#inspect-the-contributing-factors" aria-label="Permalink to &quot;Inspect the contributing factors&quot;">​</a></h2><p>Each card shows a component&#39;s latest available value and a sparkline. Click the card to inspect the underlying results.</p><table tabindex="0"><thead><tr><th>Card</th><th>What contributes</th><th>Where it opens</th></tr></thead><tbody><tr><td><strong>Charts</strong></td><td>Platform chart positions across countries and categories; higher positions contribute more</td><td><a href="/features/my-charts.html">My Charts</a></td></tr><tr><td><strong>Editorial</strong></td><td>Recent platform-curated features and qualifying web placements; placement position, publication strength, and age matter</td><td><a href="/features/my-placements.html">My Placements</a></td></tr><tr><td><strong>Search</strong></td><td>Observed show-level keyword positions across the four listening platforms, weighted by the chart visibility of shows ranking for those terms</td><td><a href="/features/show-visibility.html">Organic Visibility</a></td></tr></tbody></table><p><strong>Read each component against its own history.</strong> The cards have different display scales. Their numbers are neither percentages of the total nor values you can add together to calculate the headline score. A smaller number on one card does not by itself identify your biggest opportunity.</p><h2 id="understand-the-scoring-explanation" tabindex="-1">Understand the scoring explanation <a class="header-anchor" href="#understand-the-scoring-explanation" aria-label="Permalink to &quot;Understand the scoring explanation&quot;">​</a></h2><p>The <strong>How scoring works</strong> section introduces Charts, Editorial, and Search. They contribute with different weights, and the overall score also reflects the show&#39;s recorded activity and Apple listing status. Improvements do not translate into equal increments on the displayed scale.</p><p>The section distinguishes <strong>Apple listing status</strong>, <strong>Recorded activity</strong>, and <strong>Global rank</strong>. Show optimization and Planner alignment scores are separate from the Visibility Score, and a regular schedule does not earn a separate consistency bonus. Recent activity and listing status can affect the calculation; a metadata edit matters to visibility when the observed discovery results change.</p><p>Your global rank uses an average of recent scores over roughly the past week. The page&#39;s latest daily score, weekly chart averages, and rank can therefore move differently. See <a href="/getting-started/visibility-score-explained.html">Visibility Score Explained</a> for the full explanation.</p><h2 id="review-activity-and-signals" tabindex="-1">Review Activity and Signals <a class="header-anchor" href="#review-activity-and-signals" aria-label="Permalink to &quot;Review Activity and Signals&quot;">​</a></h2><p>The timeline groups the past thirty days into weeks and shows the score movement alongside two types of entries:</p><ul><li><strong>Actions:</strong> recorded events such as published episodes and metadata changes.</li><li><strong>Signals:</strong> observed changes such as chart improvements, editorial placements, and keyword movement.</li></ul><p>Weeks without recorded entries are marked clearly. Use the timeline to choose what to investigate. An action and a score change appearing in the same week do not establish that the action caused the change, and a quiet week can still have score movement.</p><h2 id="decide-what-to-do-next" tabindex="-1">Decide what to do next <a class="header-anchor" href="#decide-what-to-do-next" aria-label="Permalink to &quot;Decide what to do next&quot;">​</a></h2><p>If a component changes, open its detailed page before choosing a response:</p><ul><li><strong>Charts:</strong> check which chart, country, or position changed.</li><li><strong>Editorial:</strong> review platform features and web placements, including their age.</li><li><strong>Search:</strong> inspect the relevant keyword positions, then use <strong>Tracker</strong> for the terms you want to follow.</li></ul><p>Record live metadata edits and compare results over time. Check listening separately in <strong>Analytics</strong>: visibility measures discovery opportunities, rather than downloads or audience growth. A rising component confirms a change in the measured results; it does not prove which effort produced it.</p><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><p>Visibility Progress is available on paid plans. Free users see a locked preview with sample data and an <strong>Unlock Visibility Progress</strong> prompt. On a paid plan, your own score, contributing factors, and timeline appear as data becomes available.</p><p>For a practical routine connecting strategy, metadata, and results, follow <a href="/getting-started/workflow.html">the PodSEO workflow</a>.</p>',26)])])}const y=a(o,[["render",n]]);export{m as __pageData,y as default};
